        if (cmdMatch) {
            console.log(`Commands array found, length: ${cmdMatch[1].length}`);
            // Count how many command objects
            const count = (cmdMatch[1].match(/"command"/g) || []).length;
            console.log(`Number of commands: ${count}`);
        }
    }

    // Check if it's JSON
    const varRegex = /var\s+\w+\s*=\s*({.*});/s;
    const varMatch = scriptContent.match(varRegex);
    if (varMatch) {
        try {
